From 944ed27f3a740f81f587687993262d547ff90c10 Mon Sep 17 00:00:00 2001
From: Scott Mason Nash <sowasred2012@gmail.com>
Date: Mon, 12 Jul 2021 12:58:36 +0100
Subject: [PATCH 1/2] remove aria-hidden attribute from body

---
 src/js/main.js | 2 --
 1 file changed, 2 deletions(-)

diff --git a/src/js/main.js b/src/js/main.js
index 1f8a12e5..967dfcc3 100644
--- a/src/js/main.js
+++ b/src/js/main.js
@@ -15,7 +15,6 @@ export const cookiePolicy = (callback = null) => {
       cookiePolicyContainer = document.createElement('dialog');
       cookiePolicyContainer.classList.add('cookie-policy');
       cookiePolicyContainer.setAttribute('open', true);
-      document.body.setAttribute('aria-hidden', true);
       document.body.appendChild(cookiePolicyContainer);
       const notifiation = new Notification(
         cookiePolicyContainer,
@@ -37,7 +36,6 @@ export const cookiePolicy = (callback = null) => {
       callback();
     }
     document.body.removeChild(cookiePolicyContainer);
-    document.body.removeAttribute('aria-hidden');
     cookiePolicyContainer = null;
   };


From f194333957e18e75b87cf934577c453f331ad235 Mon Sep 17 00:00:00 2001
From: Scott Mason Nash <sowasred2012@gmail.com>
Date: Mon, 12 Jul 2021 12:58:52 +0100
Subject: [PATCH 2/2] bunp version to 3.3.0

